import pandas as pd
import re
import random

def task_func(s: str, seed: int = 0) -> pd.DataFrame:
    random.seed(seed)
    product_choices = ['Apple', 'Banana', 'Orange', 'Pear', 'Grape']
    code_to_product = {}
    rows = []

    if not s:
        return pd.DataFrame(columns=['ID', 'Quantity', 'Code', 'Price', 'Product', 'Description'])

    for line in s.splitlines():
        line = line.strip()
        if not line:
            continue

        parts = re.split(r"\s+", line, maxsplit=4)
        if len(parts) < 5:
            continue

        id_str, qty_str, code, price_str, description = parts
        code = code.strip()
        description = description.strip()

        if code not in code_to_product:
            code_to_product[code] = random.choice(product_choices)

        rows.append({
            'ID': int(id_str.strip()),
            'Quantity': int(qty_str.strip()),
            'Code': code,
            'Price': int(price_str.strip()),
            'Product': code_to_product[code],
            'Description': description
        })

    return pd.DataFrame(rows, columns=['ID', 'Quantity', 'Code', 'Price', 'Product', 'Description'])
