# Constants
LETTERS = string.ascii_letters

def task_func(list_of_lists):
    """
    Replace each nested sublist with a random letter and return
    a dictionary with counts of the generated letters.
    """
    counts = Counter()

    def walk(obj):
        if isinstance(obj, list):
            letter = random.choice(LETTERS)
            counts[letter] += 1
            for item in obj:
                if isinstance(item, list):
                    walk(item)

    for item in list_of_lists:
        if isinstance(item, list):
            walk(item)

    return dict(counts)
