import numpy as np
import itertools

def task_func(data_list, file_name):
    def _to_float(value):
        if value is None:
            return np.nan
        if isinstance(value, (bool, np.bool_)):
            return np.nan
        try:
            return float(value)
        except (TypeError, ValueError):
            return np.nan

    if not data_list:
        with open(file_name, "w", encoding="utf-8") as f:
            f.write("")
        return []

    numeric_rows = [
        [_to_float(v) for v in itertools.islice(row, 1, None)]
        for row in data_list
    ]

    columns = list(itertools.zip_longest(*numeric_rows, fillvalue=np.nan))
    means = []

    for col in columns:
        arr = np.asarray(col, dtype=float)
        if arr.size == 0 or np.all(np.isnan(arr)):
            means.append(np.nan)
        else:
            means.append(float(np.nanmean(arr)))

    with open(file_name, "w", encoding="utf-8") as f:
        for idx, mean_value in enumerate(means, start=2):
            f.write(f"Position {idx}: {mean_value}\n")

    return means
