import numpy as np
import matplotlib.pyplot as plt
import re
from collections import Counter

def task_func(mystrings, text):
    if text is None or (isinstance(text, str) and text.strip() == ""):
        raise ValueError("If the input text is empty.")

    if mystrings is None:
        items = []
    elif isinstance(mystrings, str):
        # Keep a single string as one item unless it is clearly multiline/comma-separated.
        if "\n" in mystrings or "," in mystrings:
            items = [part for part in re.split(r"[,\n]+", mystrings) if part.strip()]
        else:
            items = [mystrings]
    else:
        items = list(mystrings)

    normalized = []
    for item in items:
        if item is None:
            continue
        s = str(item).strip()
        if not s:
            continue
        s = re.sub(r"\s+", "_", s.lower())
        normalized.append(s)

    counts = Counter(normalized)

    ordered_words = []
    seen = set()
    for word in normalized:
        if word not in seen:
            seen.add(word)
            ordered_words.append(word)

    fig, ax = plt.subplots()
    if ordered_words:
        ax.bar(ordered_words, [counts[word] for word in ordered_words])
    else:
        ax.bar([], [])

    ax.set_xlabel("Words")
    ax.set_ylabel("Frequency")
    ax.tick_params(axis="x", rotation=45)
    plt.setp(ax.get_xticklabels(), ha="right")
    fig.tight_layout()

    return ax
