import collections
import pandas as pd

def task_func(my_tuple, path_csv_files):
    """
    Count occurrences of each unique value in the specified columns
    across multiple CSV files.

    Parameters
    ----------
    my_tuple : tuple/list/str
        Column name or names to count.
    path_csv_files : iterable or str
        Paths to CSV files.

    Returns
    -------
    dict
        {column_name: {value: count, ...}, ...}
    """
    import os

    # Normalize column names
    if my_tuple is None:
        columns = []
    elif isinstance(my_tuple, (tuple, list, set)):
        columns = list(my_tuple)
    else:
        columns = [my_tuple]

    # Normalize file paths
    if path_csv_files is None:
        files = []
    elif isinstance(path_csv_files, (str, bytes, os.PathLike)):
        files = [path_csv_files]
    else:
        files = list(path_csv_files)

    counters = {col: collections.Counter() for col in columns}

    for csv_file in files:
        df = pd.read_csv(csv_file)
        for col in columns:
            if col in df.columns:
                values = df[col].dropna().tolist()
                counters[col].update(values)

    return {col: dict(counter) for col, counter in counters.items()}
