import nltk
from string import punctuation
import pandas as pd

def task_func(text):
    if not isinstance(text, str):
        raise ValueError("text must be a string")

    counts = {}
    order = []

    for token in text.split():
        if not token.startswith("$"):
            continue

        # Ignore tokens that are entirely punctuation (including just "$")
        if len(token) == 1 or all(ch in punctuation for ch in token[1:]):
            continue

        if token not in counts:
            counts[token] = 0
            order.append(token)
        counts[token] += 1

    return pd.DataFrame(
        {"Word": order, "Frequency": [counts[word] for word in order]}
    )
